using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Shared evaluation infrastructure: telemetry, quality evaluators, and reporting.
/// </summary>
internal static class EvalSetup
{
    private static readonly string ResultsDir =
        Path.Combine(Path.GetDirectoryName(typeof(EvalSetup).Assembly.Location)!, "eval-results");

    /// <summary>
    /// Configures OpenTelemetry tracing for eval runs.
    /// </summary>
    public static TracerProvider CreateTelemetry()
    {
        return Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddHttpClientInstrumentation()
            .AddOtlpExporter()
            .AddConsoleExporter()
            .Build()!;
    }

    /// <summary>
    /// Creates a reporting configuration that stores results on disk for comparison.
    /// </summary>
    public static ReportingConfiguration CreateReportingConfig(
        IChatClient chatClient,
        string scenarioName)
    {
        var storage = new DiskBasedResultStore(ResultsDir);

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return new ReportingConfiguration(
            storage: storage,
            evaluators: evaluators,
            chatClient: chatClient,
            scenarioName: scenarioName);
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

[TestClass]
public sealed class QualityTests
{
    private static TracerProvider? s_telemetry;

    [ClassInitialize]
    public static void Init(TestContext _) => s_telemetry = EvalSetup.CreateTelemetry();

    [ClassCleanup]
    public static void Cleanup() => s_telemetry?.Dispose();

    [TestMethod]
    public async Task Coach_responds_with_relevant_guidance()
    {
        // Arrange
        var chatClient = CreateChatClient();
        var config = EvalSetup.CreateReportingConfig(chatClient, nameof(Coach_responds_with_relevant_guidance));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "How do I improve my sprint retrospectives?")
        };

        // Act
        var response = await chatClient.GetResponseAsync(messages);

        // Assert & Evaluate
        await config.EvaluateAsync(
            messages,
            response,
            additionalContext: null);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Text.Length > 0, "Response should not be empty.");
    }

    [TestMethod]
    public async Task Coach_handles_followup_questions()
    {
        // Arrange
        var chatClient = CreateChatClient();
        var config = EvalSetup.CreateReportingConfig(chatClient, nameof(Coach_handles_followup_questions));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is a good team standup format?"),
            new(ChatRole.Assistant, "A common format is: what I did yesterday, what I'll do today, and any blockers."),
            new(ChatRole.User, "How long should it last?")
        };

        // Act
        var response = await chatClient.GetResponseAsync(messages);

        // Assert & Evaluate
        await config.EvaluateAsync(
            messages,
            response,
            additionalContext: null);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Text.Length > 0, "Response should not be empty.");
    }

    private static IChatClient CreateChatClient()
    {
        // Uses AZURE_OPENAI_ENDPOINT and AZURE_OPENAI_API_KEY environment variables.
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT env var.");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_API_KEY env var.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }
}

using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Evals;

/// <summary>
/// Runs the same scenarios against two model deployments and produces a comparison report.
/// Set COMPARE_MODEL env var to override the comparison target (default: gpt-4o).
/// </summary>
[TestClass]
public sealed class CompareTests
{
    private static readonly string ResultsDir =
        Path.Combine(Path.GetDirectoryName(typeof(CompareTests).Assembly.Location)!, "eval-results");

    [TestMethod]
    public async Task Compare_models_on_coaching_prompt()
    {
        var prompt = new List<ChatMessage>
        {
            new(ChatRole.User, "Give me three tips for running better 1:1 meetings.")
        };

        var baselineModel = "gpt-4o-mini";
        var compareModel = Environment.GetEnvironmentVariable("COMPARE_MODEL") ?? "gpt-4o";

        // Run baseline
        var baselineClient = CreateChatClient(baselineModel);
        var baselineConfig = EvalSetup.CreateReportingConfig(baselineClient, $"compare-{baselineModel}");
        var baselineResponse = await baselineClient.GetResponseAsync(prompt);
        await baselineConfig.EvaluateAsync(prompt, baselineResponse, additionalContext: null);

        // Run comparison
        var compareClient = CreateChatClient(compareModel);
        var compareConfig = EvalSetup.CreateReportingConfig(compareClient, $"compare-{compareModel}");
        var compareResponse = await compareClient.GetResponseAsync(prompt);
        await compareConfig.EvaluateAsync(prompt, compareResponse, additionalContext: null);

        // Both should produce non-empty responses
        Assert.IsTrue(baselineResponse.Text.Length > 0);
        Assert.IsTrue(compareResponse.Text.Length > 0);
    }

    private static IChatClient CreateChatClient(string deployment)
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_ENDPOINT env var.");
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? throw new InvalidOperationException("Set AZURE_OPENAI_API_KEY env var.");

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient(deployment)
            .AsIChatClient();
    }
}

