using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.AI.Evaluation.Reporting.Storage;
using OpenTelemetry;
using OpenTelemetry.Resources;
using OpenTelemetry.Trace;

namespace MyApp.Evals;

/// <summary>
/// Shared evaluation infrastructure: telemetry, quality evaluators, and reporting.
/// </summary>
internal static class EvalSetup
{
    private static readonly string ResultsDir =
        Path.Combine(Path.GetDirectoryName(typeof(EvalSetup).Assembly.Location)!, "eval-results");

    /// <summary>
    /// Configures OpenTelemetry tracing for eval runs.
    /// </summary>
    public static TracerProvider CreateTelemetry()
    {
        return Sdk.CreateTracerProviderBuilder()
            .SetResourceBuilder(ResourceBuilder.CreateDefault().AddService("MyApp.Evals"))
            .AddSource("Microsoft.Extensions.AI")
            .AddHttpClientInstrumentation()
            .AddOtlpExporter()
            .AddConsoleExporter()
            .Build()!;
    }

    /// <summary>
    /// Creates a reporting configuration that stores results on disk for comparison.
    /// </summary>
    public static ReportingConfiguration CreateReportingConfig(
        IChatClient chatClient,
        string scenarioName)
    {
        var storage = new DiskBasedResultStore(ResultsDir);

        var evaluators = new IEvaluator[]
        {
            new CoherenceEvaluator(),
            new RelevanceEvaluator(),
            new FluencyEvaluator(),
            new GroundednessEvaluator(),
        };

        return new ReportingConfiguration(
            storage: storage,
            evaluators: evaluators,
            chatClient: chatClient,
            scenarioName: scenarioName);
    }
}

